        .map_err(|_| SshForwardErrorCode::StoreIo.command_error())?
    {
        scope
            .reconcile_known_scope(&known_scopes, UtcTimestamp::now())
            .map_err(|_| SshForwardErrorCode::StoreIo.command_error())?;
    }
    let active = self.active_scope.lock().await.clone();
    Ok(OpenClientResult {
